save('STATUS.json',dict(identity=s['identity'],version=175,status='THREE_CYCLES_COMPLETE_AUDITED',verdict=s['verdict'],GitHub_pushed=False,core_adopted=False))
files=[p for p in H.iterdir() if p.is_file() and p.suffix in ('.json','.md','.py','.csv') and p.name not in ('BUNDLE_MANIFEST.json','PACKAGE.json')]
